<?php
declare(strict_types=1);
require_once __DIR__.'/ai-makerworld.php';

function aiSchema():void {
 $db=sql();
 $db->exec('CREATE TABLE IF NOT EXISTS ai_drafts(id TEXT PRIMARY KEY,product_json TEXT NOT NULL,meta_json TEXT NOT NULL,status TEXT NOT NULL,duplicate_id TEXT,duplicate_decision TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)');
 $db->exec('CREATE TABLE IF NOT EXISTS ai_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,role TEXT NOT NULL,text TEXT NOT NULL,created_at TEXT NOT NULL)');
 $db->exec('CREATE TABLE IF NOT EXISTS ai_events(id INTEGER PRIMARY KEY AUTOINCREMENT,draft_id TEXT,action TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL)');
}
function aiDefaults():array {return ['model'=>'gemini-3.5-flash-lite','imageModel'=>'gemini-3.1-flash-image','temperature'=>0.4,'maxOutputTokens'=>20000,'maxProducts'=>20,'instructions'=>'Escribe todos los campos visibles al cliente exclusivamente en español de México, incluso cuando el título y la descripción originales estén en otro idioma.','prices'=>['PLA'=>220,'PETG'=>280,'TPU'=>420,'kwh'=>2.5,'watts'=>150,'wearHour'=>3.25,'laborHour'=>80,'packaging'=>8,'extraMaterial'=>0,'assembly'=>0,'painting'=>0,'wastePercent'=>10,'commissionPercent'=>5,'complexitySurchargePercent'=>25,'marginMin'=>25,'marginRecommended'=>40,'marginPremium'=>55]];}
function aiConfig():array {$stored=one("SELECT data FROM settings WHERE id='ai-products'");$config=$stored?json_decode($stored['data'],true):[];if(!is_array($config))$config=[];$config['model']='gemini-3.5-flash-lite';return array_replace_recursive(aiDefaults(),$config);}
function aiKeyFile():string {return __DIR__.'/database/gemini-key.txt';}
function aiKey():string {$env=getenv('GEMINI_API_KEY');if(is_string($env)&&trim($env)!=='')return trim($env);return is_file(aiKeyFile())?trim((string)file_get_contents(aiKeyFile())):'';}
function aiLog(?string $id,string $action,string $detail=''):void {run('INSERT INTO ai_events(draft_id,action,detail,created_at) VALUES(?,?,?,?)',[$id,$action,substr($detail,0,1000),gmdate('c')]);}
function aiText(mixed $value,int $max=300):string {return is_string($value)?mbTrim($value,$max):'';}
function mbTrim(string $value,int $max):string {$value=trim(strip_tags($value));if(strlen($value)<=$max)return $value;$cut=substr($value,0,$max);while($cut!==''&&!preg_match('//u',$cut))$cut=substr($cut,0,-1);return $cut;}
function aiNumber(mixed $value,float $min,float $max,float $default=0):float {return is_numeric($value)&&is_finite((float)$value)?max($min,min($max,(float)$value)):$default;}
function aiList(mixed $value,int $count=12,int $max=100):array {return is_array($value)?array_values(array_filter(array_map(fn($v)=>aiText($v,$max),array_slice($value,0,$count)))):[];}
function aiPrice(float $grams,float $hours,string $material,array $config,string $difficulty='Media'):array {
 $p=$config['prices'];$costKg=(float)($p[strtoupper($material)]??$p['PLA']);
 $materialCost=$grams/1000*$costKg*(1+(float)$p['wastePercent']/100);
 $electricity=$hours*(float)$p['watts']/1000*(float)$p['kwh'];
 $wear=$hours*(float)$p['wearHour'];
  $complexity=strtolower($difficulty);$isComplex=str_contains($complexity,'dif')||str_contains($complexity,'alta')||str_contains($complexity,'complej');
  $labor=max(0.25,min(2,$hours*0.15))*(float)$p['laborHour']*($isComplex?1+(float)$p['complexitySurchargePercent']/100:1);
 $other=(float)$p['packaging']+(float)$p['extraMaterial']+(float)$p['assembly']+(float)$p['painting'];
 $cost=round($materialCost+$electricity+$wear+$labor+$other,2);$commission=(float)$p['commissionPercent']/100;
 $tier=fn(float $margin)=>round($cost/max(0.05,1-$commission-$margin/100),2);
 $minimum=$tier((float)$p['marginMin']);$recommended=$tier((float)$p['marginRecommended']);$premium=$tier((float)$p['marginPremium']);
  return ['filament'=>round($materialCost,2),'electricity'=>round($electricity,2),'wear'=>round($wear,2),'labor'=>round($labor,2),'other'=>round($other,2),'cost'=>$cost,'minimum'=>$minimum,'normal'=>round(($minimum+$recommended)/2,2),'recommended'=>$recommended,'premium'=>$premium,'offer'=>round(max($minimum,$recommended*0.9),2),'profit'=>round($recommended*(1-$commission)-$cost,2),'complexityApplied'=>$isComplex,'commissionPercent'=>$p['commissionPercent'],'marginPercent'=>$p['marginRecommended'],'estimated'=>true];
}
function aiValidateConfig(array $body):array {
 $c=aiDefaults();$c['model']='gemini-3.5-flash-lite';$imageModel=aiText($body['imageModel']??'',80);if(!preg_match('/^[a-zA-Z0-9._-]{3,80}$/',$imageModel))fail(400,'Modelo de imagen inválido.');$c['imageModel']=$imageModel;
 $c['temperature']=aiNumber($body['temperature']??null,0,2,0.7);$c['maxOutputTokens']=(int)aiNumber($body['maxOutputTokens']??null,1024,65536,20000);$c['maxProducts']=(int)aiNumber($body['maxProducts']??null,1,20,20);$c['instructions']=aiText($body['instructions']??'',3000);
 $prices=$body['prices']??null;if(!is_array($prices))fail(400,'Revisa la configuración de precios.');foreach($c['prices'] as $key=>$default){$max=str_contains($key,'Percent')?80:($key==='watts'?2000:100000);$c['prices'][$key]=aiNumber($prices[$key]??null,0,$max,(float)$default);}if($c['prices']['marginPremium']+$c['prices']['commissionPercent']>=90)fail(400,'Reduce el margen premium o la comisión.');return $c;
}
function aiDraft(array $row):array {return ['id'=>$row['id'],'product'=>json_decode($row['product_json'],true),'meta'=>json_decode($row['meta_json'],true),'status'=>$row['status'],'duplicateId'=>$row['duplicate_id'],'duplicateDecision'=>$row['duplicate_decision'],'createdAt'=>$row['created_at'],'updatedAt'=>$row['updated_at']];}
function aiDrafts():array {return array_map('aiDraft',rows('SELECT * FROM ai_drafts ORDER BY created_at DESC'));}
function aiSimilar(string $name,string $category,string $description='',?string $exclude=null):?string {$normalize=function($s){$ascii=function_exists('iconv')?iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s):$s;return preg_replace('/[^a-z0-9]+/','',strtolower($ascii?:$s));};$a=$normalize($name);if(strlen($a)<4)return null;foreach(products(true) as $p){if($p['id']===$exclude)continue;$b=$normalize($p['name']);similar_text($a,$b,$percent);$sameCategory=$category===''||$p['categoryId']===$category;$content=0;if($description!==''&&$sameCategory){$descA=substr($normalize($description),0,500);$descB=substr($normalize($p['description']??''),0,500);if($descA!==''&&$descB!=='')similar_text($descA,$descB,$content);}if($a===$b||($sameCategory&&($percent>=78||($percent>=60&&$content>=75))))return $p['id'];}return null;}
function aiSlugId(string $name,string $suggestion,string $fallback,array $reserved):string {$raw=$suggestion!==''?$suggestion:$name;$ascii=function_exists('iconv')?iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$raw):$raw;$slug=trim(preg_replace('/-+/','-',preg_replace('/[^a-z0-9]+/','-',strtolower($ascii?:$raw))),'-');$slug=substr($slug,0,70);if(strlen($slug)<3||one('SELECT id FROM products WHERE id=?',[$slug])||in_array($slug,$reserved,true))return 'ai-'.substr($fallback,0,20);return $slug;}
function aiBuildProduct(array $raw,array $meta,array $config,array $categories,array $images=[]):array {
 $name=aiText($raw['name']??$raw['title']??'',150);if(strlen($name)<2)fail(502,'Gemini devolvió un producto sin nombre.');
 $categoryId=aiText($raw['categoryId']??'',80);$categoryName=aiText($raw['category']??'',100);if(!in_array($categoryId,array_column($categories,'id'),true)){$categoryId='';foreach($categories as $c)if(strcasecmp($c['name'],$categoryName)===0){$categoryId=$c['id'];break;}}
 if(!$categoryId)$categoryId=$categories[0]['id']??'';if(!$categoryId)fail(409,'Crea una categoría antes de generar productos.');
 $material=strtoupper(aiText($raw['material']??'PLA',100));if(!in_array($material,['PLA','PETG','TPU'],true))$material='PLA';
 $grams=aiNumber($meta['filamentGrams']??$raw['filamentGrams']??null,1,2000,80);$hours=aiNumber($meta['printHours']??$raw['printHours']??null,0.25,100,3);
  $pricing=aiPrice($grams,$hours,$material,$config,aiText($raw['difficulty']??'',100));$dimensions=aiText($raw['dimensions']??'',200);$description=aiText($raw['description']??'',5000);
 $id=bin2hex(random_bytes(16));$now=gmdate('c');$size=in_array($raw['size']??'', ['Pequeño','Mediano','Grande'],true)?$raw['size']:'Mediano';
 $urls=[];foreach($images as $url){if(!is_string($url)||count($urls)>=12)break;try{$safe=secureUrl($url);if($safe&&!in_array($safe,$urls,true))$urls[]=$safe;}catch(Throwable){}}
 $extra=aiText($raw['extra']??'',1800);$estimated='Medidas, consumo de filamento y tiempo de impresión: verifica las estimaciones antes de fabricar.';$extra=trim($extra."\n".$estimated);
 $colors=is_array($raw['colors']??null)?implode(', ',aiList($raw['colors'],8,30)):aiText($raw['colors']??'',300);
 $p=['id'=>$id,'name'=>$name,'description'=>$description,'price'=>$pricing['recommended'],'oldPrice'=>0,'offer'=>false,'categoryId'=>$categoryId,'subcategory'=>aiText($raw['subcategory']??'',200),'dimensions'=>$dimensions,'size'=>$size,'material'=>$material,'colors'=>$colors,'fabrication'=>aiText($raw['fabrication']??'2–3 días',100),'delivery'=>aiText($raw['delivery']??'3–5 días hábiles',100),'sku'=>'AI-'.strtoupper(substr($id,0,8)),'status'=>'Disponible','stock'=>0,'unlimited'=>true,'lowStock'=>3,'featured'=>false,'isNew'=>true,'recommended'=>false,'published'=>false,'extra'=>$extra,'images'=>$urls,'createdAt'=>$now,'popularity'=>0];
 return $p;
}
function aiMeta(array $raw,array $price):array {
 $fields=['shortTitle','seoTitle','internalName','alternativeName','collection','shortDescription','audience','difficulty','seoText','metaDescription','slug','altText','imageDescription','imageFileName'];$meta=[];foreach($fields as $f)$meta[$f]=aiText($raw[$f]??'',in_array($f,['seoText','imageDescription','shortDescription'],true)?1000:250);
 foreach(['features','uses','variants','tags','keywords'] as $f)$meta[$f]=aiList($raw[$f]??[],12,120);
 foreach(['heightCm','widthCm','depthCm','weightGrams','filamentGrams','printHours'] as $f)$meta[$f]=aiNumber($raw[$f]??null,$f==='filamentGrams'?1:($f==='printHours'?0.25:0),$f==='printHours'?100:2000,$f==='filamentGrams'?80:($f==='printHours'?3:0));
 $meta['pieces']=(int)aiNumber($raw['pieces']??null,1,100,1);$meta['unitsPerPlate']=(int)aiNumber($raw['unitsPerPlate']??null,1,50,1);$meta['assembly']=(bool)($raw['assembly']??false);$meta['supports']=(bool)($raw['supports']??false);$meta['estimatedFields']=['dimensions','weightGrams','filamentGrams','printHours'];$meta['pricing']=$price;$meta['origin']='Sugerido por IA según la solicitud; no son datos confirmados de ventas o tendencias.';return $meta;
}
function aiStoreDraft(array $product,array $meta):array {$sourceId=(int)($meta['sourceId']??0);$duplicate=$sourceId?aiMwPublishedDuplicate($sourceId):null;$duplicate=$duplicate?:aiSimilar($product['name'],$product['categoryId'],$product['description']);$now=gmdate('c');run('INSERT INTO ai_drafts(id,product_json,meta_json,status,duplicate_id,duplicate_decision,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)',[$product['id'],json_encode($product,JSON_UNESCAPED_UNICODE),json_encode($meta,JSON_UNESCAPED_UNICODE),'draft',$duplicate,null,$now,$now]);aiLog($product['id'],'Gemini preparó modelo de MakerWorld',$product['name']);return aiDraft(one('SELECT * FROM ai_drafts WHERE id=?',[$product['id']]));}
function aiImageBytes(string $url):array {
 if(preg_match('~^/uploads/[a-f0-9-]+\.(png|jpg|webp)$~i',$url)){$file=__DIR__.$url;if(!is_file($file))fail(404,'Imagen no encontrada.');$bytes=file_get_contents($file);}else{
  $p=parse_url($url);$host=strtolower($p['host']??'');if(($p['scheme']??'')!=='https'||!$host||isset($p['port'])||isset($p['user'])||isset($p['pass'])||filter_var($host,FILTER_VALIDATE_IP))fail(400,'Usa una URL HTTPS pública.');
  $ips=gethostbynamel($host);if(!$ips)fail(400,'No se pudo resolver la imagen.');foreach($ips as $ip)if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))fail(400,'La URL de imagen no es pública.');
  $bytes='';$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>12,CURLOPT_RESOLVE=>[$host.':443:'.$ips[0]],CURLOPT_USERAGENT=>'CAPA3D/1.0',CURLOPT_WRITEFUNCTION=>function($handle,$chunk)use(&$bytes){if(strlen($bytes)+strlen($chunk)>4000000)return 0;$bytes.=$chunk;return strlen($chunk);}]);curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($status!==200)fail(400,'No se pudo descargar la imagen.');
 }
 if(!is_string($bytes)||strlen($bytes)<100||strlen($bytes)>4000000)fail(400,'La imagen debe pesar menos de 4 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->buffer($bytes);if(!in_array($mime,['image/png','image/jpeg','image/webp'],true))fail(400,'Usa una imagen PNG, JPG o WebP.');return [$mime,$bytes];
}
function aiGemini(array $contents,string $system,array $config):array {
 @set_time_limit(90);
 $key=aiKey();if($key==='')fail(409,'Configura tu API Key de Gemini antes de usar IA de Productos.');if(!function_exists('curl_init'))fail(503,'Este servidor no tiene cURL disponible.');
 $model=$config['model'];$url='https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent';
 $payload=['systemInstruction'=>['parts'=>[['text'=>$system]]],'contents'=>$contents,'generationConfig'=>['maxOutputTokens'=>$config['maxOutputTokens'],'responseMimeType'=>'application/json','thinkingConfig'=>['thinkingLevel'=>'low']]];
 for($attempt=0;$attempt<3;$attempt++){$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>6,CURLOPT_TIMEOUT=>55,CURLOPT_HTTPHEADER=>['Content-Type: application/json','x-goog-api-key: '.$key]]);$raw=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$error=curl_error($ch);curl_close($ch);if(!in_array($status,[0,502,503,504],true)||$attempt===2)break;sleep(($attempt+1)*2);}
 if($status===429){$quota=json_decode((string)$raw,true);$daily=false;$retry=0;foreach($quota['error']['details']??[] as $detail){foreach($detail['violations']??[] as $violation){$id=(string)($violation['quotaId']??'');if(stripos($id,'PerDay')!==false||stripos($id,'PerDayPerProject')!==false)$daily=true;}if(preg_match('/^(\d+)(?:\.\d+)?s$/',(string)($detail['retryDelay']??''),$match))$retry=max($retry,(int)$match[1]);}if($daily)fail(429,'Se agotó la cuota diaria de Gemini 3.5 Flash Lite para este proyecto. Google la restablece a medianoche del Pacífico. Los borradores ya creados se conservaron.');fail(429,'Gemini 3.5 Flash Lite alcanzó el límite temporal de solicitudes; reintenta en '.max(10,min(180,$retry?:60)).' segundos. Los borradores ya creados se conservaron.');}if($status===401||$status===403)fail(403,'La API Key de Gemini no fue aceptada o no tiene acceso al modelo.');if($status===404)fail(400,'El modelo Gemini configurado no está disponible para esta clave.');if($status===400){$detail=json_decode((string)$raw,true);$message=aiText($detail['error']['message']??'',350);fail(400,'Gemini rechazó esta solicitud'.($message!==''?': '.$message:'.'));}if($status===503)fail(503,'Gemini 3.5 Flash Lite está saturado temporalmente. Los borradores ya creados se conservan; reanuda los pendientes más tarde.');if($status===0)fail(502,'El servidor no pudo conectar con Gemini'.($error!==''?': '.aiText($error,160):'.'));if($status!==200||!is_string($raw)){$detail=json_decode((string)$raw,true);$message=aiText($detail['error']['message']??'',250);error_log('CAPA 3D Gemini HTTP '.$status.' '.$error.' '.$message);fail(502,'Gemini respondió con HTTP '.$status.'. Intenta más tarde.');}
 $response=json_decode($raw,true);$parts=$response['candidates'][0]['content']['parts']??[];$text='';foreach($parts as $part)if(isset($part['text']))$text.=$part['text'];$result=json_decode($text,true);if(!is_array($result))fail(502,'Gemini devolvió una respuesta incompleta. Intenta de nuevo.');return $result;
}
function aiGenerateImage(array $draft,array $config,string $instruction=''):array {
 @set_time_limit(90);
 $key=aiKey();if($key==='')fail(409,'Configura tu API Key de Gemini.');$p=json_decode($draft['product_json'],true);$meta=json_decode($draft['meta_json'],true);if(count($p['images']??[])>=12)fail(409,'El producto ya tiene 12 imágenes.');
 $prompt='Fotografía comercial realista de estudio, fondo neutro, solo un producto de impresión 3D: '.$p['name'].'. '.$p['description'].'. Color y material: '.$p['colors'].' '.$p['material'].'. Sin texto, marcas, logotipos ni personas. Esta imagen es ilustrativa y será revisada por el administrador. '.$instruction;
 $parts=[['text'=>substr($prompt,0,3500)]];if(!empty($p['images'][0])){try{[$mime,$bytes]=aiImageBytes($p['images'][0]);$parts[]=['inlineData'=>['mimeType'=>$mime,'data'=>base64_encode($bytes)]];}catch(Throwable){}}
 $payload=['contents'=>[['role'=>'user','parts'=>$parts]],'generationConfig'=>['responseModalities'=>['TEXT','IMAGE']]];$url='https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($config['imageModel']).':generateContent';$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE),CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>6,CURLOPT_TIMEOUT=>75,CURLOPT_HTTPHEADER=>['Content-Type: application/json','x-goog-api-key: '.$key]]);$raw=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($status===429)fail(429,'Gemini alcanzó el límite de imágenes. Intenta más tarde.');if($status===401||$status===403)fail(403,'La API Key no tiene acceso al modelo de imágenes.');if($status!==200||!is_string($raw))fail(502,'Gemini no pudo generar la imagen. Revisa el modelo configurado.');$response=json_decode($raw,true);
 foreach($response['candidates'][0]['content']['parts']??[] as $part){$blob=$part['inlineData']??null;if(!is_array($blob)||!isset($blob['data']))continue;$bytes=base64_decode($blob['data'],true);if(!is_string($bytes)||strlen($bytes)<100||strlen($bytes)>5000000)fail(502,'Gemini devolvió una imagen demasiado grande o inválida.');$mime=(new finfo(FILEINFO_MIME_TYPE))->buffer($bytes);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??null;if(!$ext)fail(502,'Gemini devolvió un formato de imagen no admitido.');$dir=__DIR__.'/uploads';if(!is_dir($dir)&&!mkdir($dir,0755,true))fail(503,'No se pudo guardar la imagen.');$name=bin2hex(random_bytes(16)).'.'.$ext;if(file_put_contents($dir.'/'.$name,$bytes,LOCK_EX)===false)fail(503,'No se pudo guardar la imagen.');chmod($dir.'/'.$name,0644);thumbnailUpload($dir.'/'.$name);$p['images'][]='/uploads/'.$name;$meta['imageDescription']='Imagen ilustrativa generada por IA; revisar forma y proporciones antes de publicar.';run('UPDATE ai_drafts SET product_json=?,meta_json=?,status=?,updated_at=? WHERE id=?',[json_encode($p,JSON_UNESCAPED_UNICODE),json_encode($meta,JSON_UNESCAPED_UNICODE),'draft',gmdate('c'),$draft['id']]);aiLog($draft['id'],'Gemini generó imagen',$name);return aiDraft(one('SELECT * FROM ai_drafts WHERE id=?',[$draft['id']]));}
 fail(502,'Gemini no devolvió una imagen. Intenta con otra descripción.');
}
function aiHandle(string $path,string $method):never {
 aiSchema();$config=aiConfig();
 if($path==='admin/ai'&&$method==='GET')answer(['config'=>$config,'keyConfigured'=>aiKey()!=='','drafts'=>aiDrafts(),'messages'=>rows('SELECT id,role,text,created_at createdAt FROM ai_messages ORDER BY id DESC LIMIT 30'),'events'=>rows('SELECT id,draft_id draftId,action,detail,created_at createdAt FROM ai_events ORDER BY id DESC LIMIT 50')]);
  if($path==='admin/ai/config'&&$method==='POST'){$body=data();$c=aiValidateConfig($body);$key=aiText($body['apiKey']??'',300);if($key!==''){if(!preg_match('/\A[A-Za-z0-9._-]{20,300}\z/',$key))fail(400,'La API Key tiene caracteres no permitidos o una longitud incorrecta.');if(file_put_contents(aiKeyFile(),$key,LOCK_EX)===false)fail(503,'No se pudo guardar la API Key.');chmod(aiKeyFile(),0600);}if(($body['clearKey']??false)===true&&is_file(aiKeyFile()))unlink(aiKeyFile());run("INSERT INTO settings(id,data) VALUES('ai-products',?) ON CONFLICT(id) DO UPDATE SET data=excluded.data",[json_encode($c,JSON_UNESCAPED_UNICODE)]);aiLog(null,'Configuración IA actualizada');answer(['config'=>$c,'keyConfigured'=>aiKey()!=='']);}
  if($path==='admin/ai/price'&&$method==='POST'){$body=data();$grams=num($body,'filamentGrams',1,2000);$hours=num($body,'printHours',0.25,100);$material=val($body,'material',100,true);$difficulty=aiText($body['difficulty']??'',100);answer(['pricing'=>aiPrice($grams,$hours,$material,$config,$difficulty)]);}
  if($path==='admin/ai/makerworld-search'&&$method==='POST'){rate('ai-makerworld-search',25,3600);$body=data();$query=val($body,'query',100,true);answer(['results'=>aiMwSearch([$query],5)]);}
 if($path==='admin/ai/image'&&$method==='POST'){$body=data();$id=val($body,'id',40,true);$draft=one('SELECT * FROM ai_drafts WHERE id=?',[$id]);if(!$draft)fail(404,'Borrador no encontrado.');rate('ai-image',12,3600);$updated=aiGenerateImage($draft,$config,aiText($body['instruction']??'',500));answer(['draft'=>$updated]);}
 if($path==='admin/ai/chat'&&$method==='POST'){
  $body=data();$bulk=($body['bulk']??false)===true;if(!$bulk)rate('ai-chat',25,3600);$batchCount=null;$excluded=[];if($bulk){$batchCount=$body['batchCount']??null;if(!is_int($batchCount)||$batchCount<1||$batchCount>5)fail(400,'Cada tanda debe contener entre 1 y 5 productos.');$ids=$body['excludeIds']??[];if(!is_array($ids)||count($ids)>3000)fail(400,'Lista de modelos descartados inválida.');foreach($ids as $id)if(is_int($id)&&$id>0)$excluded[$id]=true;}
  $message=val($body,'message',1500,true);$selected=aiText($body['selectedDraftId']??'',40);$images=$body['images']??[];if(!is_array($images)||count($images)>3)fail(400,'Puedes analizar hasta tres imágenes a la vez.');$categories=categories();if(!$categories)fail(409,'Crea una categoría antes de generar productos.');
  $history=array_reverse(rows('SELECT role,text FROM ai_messages ORDER BY id DESC LIMIT 10'));$contents=[];foreach($history as $h)$contents[]=['role'=>$h['role']==='model'?'model':'user','parts'=>[['text'=>$h['text']]]];
