function aiNormalizeDraft(array $p,array $m,array $config):array {
 $p['name']=aiText($p['name']??'',150);$p['description']=aiText($p['description']??'',5000);$p['subcategory']=aiText($p['subcategory']??'',200);$p['dimensions']=aiText($p['dimensions']??'',200);$p['colors']=aiText($p['colors']??'',300);$p['extra']=aiText($p['extra']??'',3000);$p['price']=aiNumber($p['price']??null,0,1000000,0);$p['stock']=(int)aiNumber($p['stock']??null,0,1000000,0);$p['lowStock']=(int)aiNumber($p['lowStock']??null,0,1000000,3);$p['oldPrice']=aiNumber($p['oldPrice']??null,0,1000000,0);
 foreach(['shortTitle','seoTitle','internalName','alternativeName','collection','shortDescription','audience','difficulty','seoText','metaDescription','slug','altText','imageDescription','imageFileName'] as $key)$m[$key]=aiText($m[$key]??'',in_array($key,['shortDescription','seoText','imageDescription'],true)?1000:250);
 foreach(['features','uses','variants','tags','keywords'] as $key)$m[$key]=aiList($m[$key]??[]);
 foreach(['heightCm','widthCm','depthCm','weightGrams','filamentGrams','printHours'] as $key)$m[$key]=aiNumber($m[$key]??null,$key==='filamentGrams'?1:($key==='printHours'?0.25:0),$key==='printHours'?100:2000,$key==='filamentGrams'?80:($key==='printHours'?3:0));
  $m['pieces']=(int)aiNumber($m['pieces']??null,1,100,1);$m['unitsPerPlate']=(int)aiNumber($m['unitsPerPlate']??null,1,50,1);$m['assembly']=(bool)($m['assembly']??false);$m['supports']=(bool)($m['supports']??false);$m['estimatedFields']=['dimensions','weightGrams','filamentGrams','printHours'];$m['pricing']=aiPrice((float)$m['filamentGrams'],(float)$m['printHours'],$p['material']??'PLA',$config,$m['difficulty']);
 if(!is_array($p['images']??null)||count($p['images'])>12)fail(400,'Añade hasta 12 imágenes.');foreach($p['images'] as $url)secureUrl($url);$p['published']=false;validProduct($p);return [$p,$m];
}
